import React from 'react';
import AppLayout from '../components/AppLayout';
import { RestaurantCard, C } from '../components/UI';
import { RESTAURANTS } from '../data/mockData';
import { MapPin } from 'lucide-react';

export default function NearbyScreen() {
  return (
    <AppLayout>
      <div style={{ padding: '20px 16px 0' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
          <h1 style={{ fontSize: 22, fontWeight: 800, color: '#fff' }}>Nearby</h1>
          <div style={{ display: 'flex', alignItems: 'center', gap: 4, color: C.orange, fontSize: 12, fontWeight: 600 }}>
            <MapPin size={14} />
            <span>Avadi, Chennai</span>
          </div>
        </div>
        <p style={{ fontSize: 13, color: '#666', marginBottom: 20 }}>Restaurants near you</p>

        {/* Map placeholder */}
        <div style={{
          height: 180, background: '#1e1e1e', borderRadius: 16,
          border: `1px solid ${C.border}`, marginBottom: 20,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          flexDirection: 'column', gap: 8, color: '#444',
        }}>
          <MapPin size={32} />
          <span style={{ fontSize: 13 }}>Map View — Coming Soon</span>
        </div>

        <p style={{ fontSize: 14, fontWeight: 700, color: '#fff', marginBottom: 12 }}>All Restaurants</p>
        {RESTAURANTS.map(r => <RestaurantCard key={r.id} restaurant={r} />)}
      </div>
    </AppLayout>
  );
}
